window.CODE = Object.assign(window.CODE || {}, {"ch15/approval_graph.py":"\"\"\"Human approval with interrupt(), saved to SQLite so the approval can come after a restart.\n\ninterrupt(payload)    pauses the graph and returns payload to the caller\nCommand(resume=value) continues; interrupt() then RETURNS value inside the node\n\nRun:  python approval_graph.py\n\"\"\"\nimport sqlite3\nimport sys\nfrom pathlib import Path\nfrom typing import TypedDict\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nfrom clinic import request_appointment  # noqa: E402\nfrom langgraph.checkpoint.sqlite import SqliteSaver  # noqa: E402\nfrom langgraph.graph import END, START, StateGraph  # noqa: E402\nfrom langgraph.types import Command, interrupt  # noqa: E402\n\nDB = HERE / \"checkpoints.db\"\n\n\nclass State(TypedDict, total=False):\n    doctor: str\n    day: str\n    patient_name: str\n    decision: dict\n    result: dict\n\n\ndef ask_staff(state: State) -> dict:\n    # Everything before interrupt() runs again on resume, so keep side effects AFTER it.\n    decision = interrupt({\"question\": \"Approve this appointment request?\",\n                          \"request\": {k: state[k] for k in (\"doctor\", \"day\", \"patient_name\")}})\n    return {\"decision\": decision}\n\n\ndef book(state: State) -> dict:\n    result = request_appointment(state[\"doctor\"], state[\"day\"], state[\"patient_name\"])\n    if \"error\" not in result:\n        result.update(status=\"approved\", approved_by=state[\"decision\"].get(\"by\"))\n    return {\"result\": result}\n\n\ndef decline(state: State) -> dict:\n    return {\"result\": {\"status\": \"declined\", \"reason\": state[\"decision\"].get(\"reason\", \"\")}}\n\n\ndef build(checkpointer):\n    b = StateGraph(State)\n    b.add_node(\"ask_staff\", ask_staff)\n    b.add_node(\"book\", book)\n    b.add_node(\"decline\", decline)\n    b.add_edge(START, \"ask_staff\")\n    b.add_conditional_edges(\"ask_staff\", lambda s: \"book\" if s[\"decision\"].get(\"approved\") else \"decline\")\n    b.add_edge(\"book\", END)\n    b.add_edge(\"decline\", END)\n    return b.compile(checkpointer=checkpointer)\n\n\nif __name__ == \"__main__\":\n    DB.unlink(missing_ok=True)\n    config = {\"configurable\": {\"thread_id\": \"req-asha-001\"}}\n\n    # --- Process 1: the agent runs and pauses\n    with sqlite3.connect(DB, check_same_thread=False) as conn:\n        graph = build(SqliteSaver(conn))\n        out = graph.invoke({\"doctor\": \"Dr Rao\", \"day\": \"Thu\", \"patient_name\": \"Asha Verma\"}, config)\n        print(\"Paused:\", out[\"__interrupt__\"][0].value)\n        print(\"Next node waiting:\", graph.get_state(config).next)\n\n    # --- Later, maybe after a server restart: a NEW graph object, same database\n    with sqlite3.connect(DB, check_same_thread=False) as conn:\n        graph = build(SqliteSaver(conn))\n        out = graph.invoke(Command(resume={\"approved\": True, \"by\": \"staff-17\"}), config)\n        print(\"Resumed:\", out[\"result\"])\n","ch15/fanout.py":"\"\"\"Map-reduce with the Send API: check several departments IN PARALLEL, then combine.\n\nA conditional edge can return a list of Send(\"node\", input). LangGraph runs one copy of\nthe node per Send, at the same time, and a reducer (operator.add) merges their results.\n\nRun:  python fanout.py\n\"\"\"\nimport operator\nimport sys\nfrom pathlib import Path\nfrom typing import Annotated, TypedDict\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nfrom clinic import get_doctor_schedule  # noqa: E402\nfrom langgraph.graph import END, START, StateGraph  # noqa: E402\nfrom langgraph.types import Send  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\nfrom pydantic import BaseModel  # noqa: E402\n\n\nclass Departments(BaseModel):\n    departments: list[str]\n\n\nclass State(TypedDict, total=False):\n    question: str\n    departments: list[str]\n    findings: Annotated[list[str], operator.add]     # REDUCER: results from parallel nodes are added together\n    answer: str\n\n\nmodel = get_model()\n\n\ndef plan(state: State) -> dict:\n    d = model.with_structured_output(Departments).invoke(\n        f\"Which of these departments does the question need: cardiology, orthopaedics, paediatrics?\\n{state['question']}\")\n    return {\"departments\": d.departments}\n\n\ndef fan_out(state: State) -> list[Send]:\n    return [Send(\"check_department\", {\"department\": d}) for d in state[\"departments\"]]\n\n\ndef check_department(item: dict) -> dict:\n    \"\"\"Runs once per department, in parallel. Gets its own small input, not the whole state.\"\"\"\n    sched = get_doctor_schedule(item[\"department\"])\n    return {\"findings\": [f\"{item['department']}: {sched.get('doctors', sched)}\"]}\n\n\ndef combine(state: State) -> dict:\n    facts = \"\\n\".join(sorted(state[\"findings\"]))\n    reply = model.invoke(f\"Answer using only these facts.\\nFacts:\\n{facts}\\nQuestion: {state['question']}\")\n    return {\"answer\": reply.content}\n\n\nb = StateGraph(State)\nb.add_node(\"plan\", plan)\nb.add_node(\"check_department\", check_department)\nb.add_node(\"combine\", combine)\nb.add_edge(START, \"plan\")\nb.add_conditional_edges(\"plan\", fan_out, [\"check_department\"])\nb.add_edge(\"check_department\", \"combine\")      # combine waits for ALL parallel branches\nb.add_edge(\"combine\", END)\ngraph = b.compile()\n\nif __name__ == \"__main__\":\n    out = graph.invoke({\"question\": \"My son needs a paediatrician and I need a cardiologist. Is any day good for both?\"})\n    print(\"Departments:\", out[\"departments\"])\n    print(\"Findings:   \", out[\"findings\"])\n    print(\"Answer:     \", out[\"answer\"])\n","ch15/self_correct.py":"\"\"\"A self-correcting graph: extract a booking request, check it in code, and loop back with\nthe exact problems until it is valid, or hand over after 3 attempts.\n\n    extract -> validate --ok--> done\n                  |--problems (attempt < 3)--> extract   (a cycle)\n                  |--problems (attempt = 3)--> handoff\n\nRun:  python self_correct.py\n\"\"\"\nimport sys\nfrom pathlib import Path\nfrom typing import TypedDict\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nfrom clinic import SCHEDULE  # noqa: E402\nfrom langgraph.graph import END, START, StateGraph  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\nfrom pydantic import BaseModel  # noqa: E402\n\nMAX_ATTEMPTS = 3\nDOCTORS = {doc: days for dept in SCHEDULE.values() for doc, days in dept.items()}\n\n\nclass Booking(BaseModel):\n    doctor: str\n    day: str\n    patient_name: str\n\n\nclass State(TypedDict, total=False):\n    message: str\n    booking: Booking\n    problems: list[str]\n    attempts: int\n    result: str\n\n\nextractor = get_model().with_structured_output(Booking)\n\n\ndef extract(state: State) -> dict:\n    prompt = (f\"Extract the appointment request from this message: {state['message']}\\n\"\n              f\"Known doctors and days: {DOCTORS}. Use the exact doctor name and a 3-letter day like Thu.\")\n    if state.get(\"problems\"):                            # feedback from the previous attempt\n        prompt += \"\\nYour previous answer had these problems, fix them: \" + \"; \".join(state[\"problems\"])\n    booking = extractor.invoke(prompt)\n    print(f\"  attempt {state.get('attempts', 0) + 1}: {booking.model_dump()}\")\n    return {\"booking\": booking, \"attempts\": state.get(\"attempts\", 0) + 1}\n\n\ndef validate(state: State) -> dict:\n    \"\"\"Plain code checks: reliable, free and testable.\"\"\"\n    b, problems = state[\"booking\"], []\n    if b.doctor not in DOCTORS:\n        problems.append(f\"'{b.doctor}' is not a doctor here; choose from {list(DOCTORS)}\")\n    elif b.day not in DOCTORS[b.doctor]:\n        problems.append(f\"{b.doctor} works only on {DOCTORS[b.doctor]}, not '{b.day}'\")\n    if len(b.patient_name.split()) < 2:\n        problems.append(\"patient_name must be the full name from the message\")\n    return {\"problems\": problems}\n\n\ndef next_step(state: State) -> str:\n    if not state[\"problems\"]:\n        return \"done\"\n    return \"handoff\" if state[\"attempts\"] >= MAX_ATTEMPTS else \"extract\"\n\n\ndef done(state: State) -> dict:\n    return {\"result\": f\"Request ready for staff: {state['booking'].model_dump()}\"}\n\n\ndef handoff(state: State) -> dict:\n    return {\"result\": \"Could not understand the request; passing to the front desk. Problems: \" + \"; \".join(state[\"problems\"])}\n\n\nbuilder = StateGraph(State)\nfor name, fn in [(\"extract\", extract), (\"validate\", validate), (\"done\", done), (\"handoff\", handoff)]:\n    builder.add_node(name, fn)\nbuilder.add_edge(START, \"extract\")\nbuilder.add_edge(\"extract\", \"validate\")\nbuilder.add_conditional_edges(\"validate\", next_step, [\"extract\", \"done\", \"handoff\"])\nbuilder.add_edge(\"done\", END)\nbuilder.add_edge(\"handoff\", END)\ngraph = builder.compile()\n\nif __name__ == \"__main__\":\n    for msg in [\"Please book the heart doctor Rao for me on thursday. I'm Meena Pillai.\",\n                \"Book Dr Gupta tomorrow for Ali\"]:\n        print(msg)\n        print(\" ->\", graph.invoke({\"message\": msg})[\"result\"], \"\\n\")\n","ch15/store_memory.py":"\"\"\"Long-term memory across conversations with a LangGraph Store.\n\nCheckpointer = memory of ONE conversation (thread). Store = memory across ALL conversations,\norganised in namespaces like (\"patients\", \"UHID-1001\"). Same idea as Chapter 10's MemoryStore.\n\nRun:  python store_memory.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom langgraph.checkpoint.memory import InMemorySaver  # noqa: E402\nfrom langgraph.graph import START, MessagesState, StateGraph  # noqa: E402\nfrom langgraph.runtime import Runtime  # noqa: E402\nfrom langgraph.store.memory import InMemoryStore  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\nmodel = get_model()\nALLOWED = {\"preferred_language\", \"preferred_doctor\"}     # only safe, useful facts (Chapter 10)\n\n\ndef remember(state: MessagesState, config, runtime: Runtime) -> dict:\n    \"\"\"Save allowed facts the patient states. A real app would extract them with the model.\"\"\"\n    ns = (\"patients\", config[\"configurable\"][\"patient_id\"])\n    text = state[\"messages\"][-1].content.lower()\n    if \"hindi\" in text:\n        runtime.store.put(ns, \"preferred_language\", {\"value\": \"Hindi\"})\n    return {}\n\n\ndef respond(state: MessagesState, config, runtime: Runtime) -> dict:\n    ns = (\"patients\", config[\"configurable\"][\"patient_id\"])\n    facts = {item.key: item.value[\"value\"] for item in runtime.store.search(ns) if item.key in ALLOWED}\n    system = f\"You are the City Clinic helpdesk. Known patient preferences: {facts or 'none'}. One sentence.\"\n    return {\"messages\": [model.invoke([(\"system\", system)] + state[\"messages\"])]}\n\n\nb = StateGraph(MessagesState)\nb.add_node(\"remember\", remember)\nb.add_node(\"respond\", respond)\nb.add_edge(START, \"remember\")\nb.add_edge(\"remember\", \"respond\")\nstore = InMemoryStore()       # PostgresStore / RedisStore in production; add index=... for search by meaning\ngraph = b.compile(checkpointer=InMemorySaver(), store=store)\n\nif __name__ == \"__main__\":\n    monday = {\"configurable\": {\"thread_id\": \"chat-mon\", \"patient_id\": \"UHID-1001\"}}\n    friday = {\"configurable\": {\"thread_id\": \"chat-fri\", \"patient_id\": \"UHID-1001\"}}   # NEW conversation\n\n    graph.invoke({\"messages\": [(\"user\", \"Please talk to me in Hindi from now on.\")]}, monday)\n    out = graph.invoke({\"messages\": [(\"user\", \"When is OPD open?\")]}, friday)\n    print(\"Friday reply:\", out[\"messages\"][-1].content)\n    print(\"Stored:\", [(i.namespace, i.key, i.value) for i in store.search((\"patients\", \"UHID-1001\"))])\n    print(\"Friday thread only has\", len(out[\"messages\"]), \"messages: the preference came from the store\")\n","ch15/subgraph.py":"\"\"\"Sub-graphs: build a self-contained graph (billing) and use it as ONE node in a bigger graph.\n\nEach team can own and test its sub-graph. Shared keys (here \"message\" and \"reply\") flow\nbetween parent and child automatically.\n\nRun:  python subgraph.py\n\"\"\"\nfrom typing import TypedDict\n\nfrom langgraph.graph import END, START, StateGraph\n\n\nclass State(TypedDict, total=False):\n    message: str\n    reply: str\n    bill_id: str          # only the billing sub-graph uses this\n\n\n# ---------------------------------------------------------------- the billing sub-graph\ndef find_bill(state: State) -> dict:\n    words = [w.strip(\".,?\") for w in state[\"message\"].split()]\n    return {\"bill_id\": next((w for w in words if w.upper().startswith(\"BILL-\")), \"\")}\n\n\ndef explain_bill(state: State) -> dict:\n    if not state[\"bill_id\"]:\n        return {\"reply\": \"Please share your bill number (it starts with BILL-).\"}\n    return {\"reply\": f\"{state['bill_id'].upper()}: OPD fee Rs 100, ECG Rs 350. Total Rs 450.\"}   # made-up data\n\n\nbilling = StateGraph(State)\nbilling.add_node(\"find_bill\", find_bill)\nbilling.add_node(\"explain_bill\", explain_bill)\nbilling.add_edge(START, \"find_bill\")\nbilling.add_edge(\"find_bill\", \"explain_bill\")\nbilling_graph = billing.compile()\n\n\n# ---------------------------------------------------------------- the parent helpdesk graph\ndef general(state: State) -> dict:\n    return {\"reply\": \"OPD runs Mon-Sat, 9-1 and 4-7.\"}\n\n\nparent = StateGraph(State)\nparent.add_node(\"billing\", billing_graph)              # a whole graph as one node\nparent.add_node(\"general\", general)\nparent.add_conditional_edges(START, lambda s: \"billing\" if \"bill\" in s[\"message\"].lower() else \"general\")\nparent.add_edge(\"billing\", END)\nparent.add_edge(\"general\", END)\nhelpdesk = parent.compile()\n\nif __name__ == \"__main__\":\n    for msg in [\"Can you explain bill-2291?\", \"Why is my bill so high?\", \"When is OPD open?\"]:\n        print(f\"{msg}\\n  -> {helpdesk.invoke({'message': msg})['reply']}\")\n    print(\"\\nNodes in the parent graph:\", list(helpdesk.get_graph().nodes))\n    print(\"Nodes including sub-graphs:\", list(helpdesk.get_graph(xray=True).nodes))\n","ch15/time_travel.py":"\"\"\"Time travel: inspect every saved checkpoint, and re-run from an earlier one with a change.\n\nUseful for debugging (\"what did the state look like before the bad step?\") and for\nletting staff correct an input and replay without starting over.\n\nRun:  python time_travel.py\n\"\"\"\nfrom typing import TypedDict\n\nfrom langgraph.checkpoint.memory import InMemorySaver\nfrom langgraph.graph import END, START, StateGraph\n\n\nclass State(TypedDict, total=False):\n    department: str\n    doctors: list[str]\n    reply: str\n\n\nSCHEDULE = {\"cardiology\": [\"Dr Mehta\", \"Dr Rao\"], \"orthopaedics\": [\"Dr Iyer\"]}\n\n\ndef lookup(state: State) -> dict:\n    return {\"doctors\": SCHEDULE.get(state[\"department\"], [])}\n\n\ndef reply(state: State) -> dict:\n    return {\"reply\": f\"{state['department']}: {', '.join(state['doctors']) or 'no doctors found'}\"}\n\n\nb = StateGraph(State)\nb.add_node(\"lookup\", lookup)\nb.add_node(\"reply\", reply)\nb.add_edge(START, \"lookup\")\nb.add_edge(\"lookup\", \"reply\")\nb.add_edge(\"reply\", END)\ngraph = b.compile(checkpointer=InMemorySaver())\n\nif __name__ == \"__main__\":\n    config = {\"configurable\": {\"thread_id\": \"t1\"}}\n    print(\"Run:\", graph.invoke({\"department\": \"cardio\"}, config)[\"reply\"])     # a typo in the input\n\n    history = list(graph.get_state_history(config))                           # newest first\n    for snap in history:\n        print(f\"  checkpoint before {snap.next or '(end)'}: {snap.values}\")\n\n    before_lookup = next(s for s in history if s.next == (\"lookup\",))\n    fixed = graph.update_state(before_lookup.config, {\"department\": \"cardiology\"})   # fork with a fix\n    print(\"Replay from the fixed checkpoint:\", graph.invoke(None, fixed)[\"reply\"])\n","common/lc_models.py":"\"\"\"One place to create LangChain chat models and embeddings for every Part C chapter.\n\nLangChain hides the provider differences, so switching OpenAI <-> Anthropic is one line:\n\n    init_chat_model(\"openai:gpt-4.1-mini\")     or     init_chat_model(\"anthropic:claude-haiku-5-5\")\n\nThis helper reads the same .env settings as llm.py (PROVIDER, OPENAI_MODEL, ANTHROPIC_MODEL).\n\n    from lc_models import get_model, get_embeddings\n    model = get_model()                  # a LangChain chat model for your PROVIDER\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\nfrom langchain.chat_models import init_chat_model\nfrom langchain_core.embeddings import Embeddings\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\n\n\ndef get_model(provider: str | None = None, temperature: float = 0, **kwargs):\n    \"\"\"A chat model with sensible production defaults: a timeout and automatic retries.\"\"\"\n    provider = provider or PROVIDER\n    return init_chat_model(f\"{provider}:{MODELS[provider]}\", temperature=temperature,\n                           timeout=float(os.getenv(\"LLM_TIMEOUT\", \"30\")),\n                           max_retries=int(os.getenv(\"LLM_RETRIES\", \"2\")), **kwargs)\n\n\nclass CourseEmbeddings(Embeddings):\n    \"\"\"Wraps llm.embed() (Chapter 6) so LangChain vector stores can use it.\n    EMBEDDINGS=openai uses text-embedding-3-small; EMBEDDINGS=local uses a free local model.\"\"\"\n\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\n        from llm import embed\n        return embed(texts)\n\n    def embed_query(self, text: str) -> list[float]:\n        return self.embed_documents([text])[0]\n\n\ndef get_embeddings() -> Embeddings:\n    return CourseEmbeddings()\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
